import java.util.Objects;

public final class BubbleSort {
    private BubbleSort() {
        // Utility class; do not instantiate.
    }

    public static void sort(int[] values) {
        Objects.requireNonNull(values, "values");

        int n = values.length;
        if (n < 2) {
            return;
        }

        for (int pass = 0; pass < n - 1; pass++) {
            boolean swapped = false;

            for (int index = 0; index < n - pass - 1; index++) {
                if (isOutOfOrder(values[index], values[index + 1])) {
                    swap(values, index, index + 1);
                    swapped = true;
                }
            }

            if (!swapped) {
                break;
            }
        }
    }

    private static boolean isOutOfOrder(int left, int right) {
        return left > right;
    }

    private static void swap(int[] values, int left, int right) {
        int temp = values[left];
        values[left] = values[right];
        values[right] = temp;
    }
}

import java.util.Arrays;

public final class BubbleSortDemo {
    private static final String SORTED_PREFIX = "Sorted array: ";
    private static final String USAGE = "Usage: java BubbleSortDemo [integers...]";

    private BubbleSortDemo() {
        // Utility class; do not instantiate.
    }

    public static void main(String[] args) {
        try {
            int[] values = parseValues(args);
            BubbleSort.sort(values);
            System.out.println(SORTED_PREFIX);
            System.out.println(Arrays.toString(values));
        } catch (IllegalArgumentException ex) {
            printUsageError(ex.getMessage());
            System.exit(1);
            return;
        }

        System.exit(0);
    }

    private static int[] parseValues(String[] args) {
        if (args.length == 0) {
            throw new IllegalArgumentException("No integers provided.");
        }

        int[] values = new int[args.length];

        for (int i = 0; i < args.length; i++) {
            try {
                values[i] = Integer.parseInt(args[i]);
            } catch (NumberFormatException ex) {
                throw new IllegalArgumentException(
                        "Invalid integer at argument " + (i + 1) + ": \"" + args[i] + "\"");
            }
        }

        return values;
    }

    private static void printUsageError(String message) {
        System.err.println(message);
        System.err.println(USAGE);
    }
}

